CREATE DEFINER=`root`@`localhost` PROCEDURE `poblar_metricas_actividad`()
BEGIN
    DECLARE v_fecha DATE;
    DECLARE v_hora TIME;
    DECLARE v_cantidad INT;
    DECLARE i INT DEFAULT 0;
    DECLARE dias INT;
    
    -- Fecha de inicio
    SET v_fecha = '2024-01-01';
    
    -- Calcular días hasta HOY (no hasta el futuro)
    SET dias = DATEDIFF(CURDATE(), v_fecha) + 1;

    WHILE i < dias DO
        -- Usuario 1: Alta actividad (1-2000)
        SET v_hora = SEC_TO_TIME(FLOOR(RAND() * 86400));
        SET v_cantidad = FLOOR(RAND() * 2000) + 1;
        INSERT INTO wevently.metricas_actividad (cantidad_ingresos, fecha_ingreso, usuario_id)
        VALUES (v_cantidad, CONCAT(v_fecha, ' ', v_hora), 1);

        -- Usuario 2: Actividad media (1-200)
        SET v_hora = SEC_TO_TIME(FLOOR(RAND() * 86400));
        SET v_cantidad = FLOOR(RAND() * 2000) + 1;
        INSERT INTO wevently.metricas_actividad (cantidad_ingresos, fecha_ingreso, usuario_id)
        VALUES (v_cantidad, CONCAT(v_fecha, ' ', v_hora), 2);

        -- Usuario 3: Actividad media (1-200)
        SET v_hora = SEC_TO_TIME(FLOOR(RAND() * 86400));
        SET v_cantidad = FLOOR(RAND() * 2000) + 1;
        INSERT INTO wevently.metricas_actividad (cantidad_ingresos, fecha_ingreso, usuario_id)
        VALUES (v_cantidad, CONCAT(v_fecha, ' ', v_hora), 3);

        -- Usuario 4: Actividad media (1-200)
        SET v_hora = SEC_TO_TIME(FLOOR(RAND() * 86400));
        SET v_cantidad = FLOOR(RAND() * 2000) + 1;
        INSERT INTO wevently.metricas_actividad (cantidad_ingresos, fecha_ingreso, usuario_id)
        VALUES (v_cantidad, CONCAT(v_fecha, ' ', v_hora), 4);

        -- Siguiente día
        SET v_fecha = DATE_ADD(v_fecha, INTERVAL 1 DAY);
        SET i = i + 1;
    END WHILE;
    
    -- Mensaje informativo
    SELECT CONCAT('Se insertaron ', dias * 4, ' registros desde 2024-01-01 hasta ', CURDATE()) AS resultado;
END ;;
DELIMITER ;
