CREATE DEFINER=`root`@`localhost` PROCEDURE `poblar_metricas_vistas_lugar`()
BEGIN
    DECLARE v_fecha DATE;
    DECLARE v_hora TIME;
    DECLARE v_cantidad INT;
    DECLARE v_lugar_id INT;
    DECLARE i INT DEFAULT 0;
    DECLARE dias INT;
    
    -- Fecha de inicio
    SET v_fecha = '2024-01-01';
    
    -- Calcular días hasta HOY
    SET dias = DATEDIFF(CURDATE(), v_fecha) + 1;

    WHILE i < dias DO
        -- Lugar 1: Alta cantidad de vistas (100-800)
        SET v_hora = SEC_TO_TIME(FLOOR(RAND() * 86400));
        SET v_cantidad = FLOOR(RAND() * 701) + 100;
        INSERT INTO wevently.metricas_vistas_lugar (cantidad_vistas, fecha_vista, lugar_id)
        VALUES (v_cantidad, CONCAT(v_fecha, ' ', v_hora), 1);

        -- Lugar 2: Cantidad media de vistas (50-400)
        SET v_hora = SEC_TO_TIME(FLOOR(RAND() * 86400));
        SET v_cantidad = FLOOR(RAND() * 351) + 50;
        INSERT INTO wevently.metricas_vistas_lugar (cantidad_vistas, fecha_vista, lugar_id)
        VALUES (v_cantidad, CONCAT(v_fecha, ' ', v_hora), 2);

        -- Lugar 3: Cantidad baja de vistas (10-150)
        SET v_hora = SEC_TO_TIME(FLOOR(RAND() * 86400));
        SET v_cantidad = FLOOR(RAND() * 141) + 10;
        INSERT INTO wevently.metricas_vistas_lugar (cantidad_vistas, fecha_vista, lugar_id)
        VALUES (v_cantidad, CONCAT(v_fecha, ' ', v_hora), 3);

        -- Siguiente día
        SET v_fecha = DATE_ADD(v_fecha, INTERVAL 1 DAY);
        SET i = i + 1;
    END WHILE;
    
    -- Mensaje informativo
    SELECT CONCAT('Se insertaron ', dias * 3, ' registros de vistas por lugar desde 2024-01-01 hasta ', CURDATE()) AS resultado;
END ;;
DELIMITER ;
